function matches(query){const words=normalize(query).trim().split(/\s+/).filter(Boolean);if(!words.length)return[];return currentRecords().filter(r=>words.every(w=>r.search.includes(w))).sort((a,b)=>{const an=normalize(displayName(a.name)),bn=normalize(displayName(b.name)),q=normalize(query);return Number(bn.startsWith(q))-Number(an.startsWith(q))||an.length-bn.length;});}
