 document.querySelectorAll('[data-palette]').forEach(b=>b.onclick=()=>{paletteMode=b.dataset.palette;for(const o of objects.values())applyPalette(o.material,paletteMode);document.querySelectorAll('[data-palette]').forEach(x=>x.setAttribute('aria-pressed',String(x===b)));$('#paletteNote').textContent=paletteMode==='natural'?'Doku tonları temsili olarak doğala yaklaştırılmıştır.':'Kırmızı–mavi damar renkleri eğitsel kodlamadır.';refresh();});
