 $('#organAnimate').onchange=async e=>{organMotion.enabled=e.target.checked;if(!e.target.checked){organMotion.restore();requestRender();return;}try{active.add('visceral');active.add('cardiovascular');await Promise.all([loadLayer('visceral'),loadLayer('cardiovascular')]);organMotion.rebuild(objects,sex);renderLayers();refresh();}catch{organMotion.enabled=false;e.target.checked=false;toast('Organlar yüklenemedi.');}};
