function renderConnectionInfo(){const panel=$('#connectionInfo');if(!panel)return;if(!labels||!$('#showConnections').checked){panel.hidden=true;return;}panel.hidden=false;if(!selected||selected.userData.record.layer!=='muscular'){panel.hidden=true;return;}const info=resolveConnections(selected.userData.record,currentRecords());if(!info){panel.innerHTML='<b>Bağlantı haritası</b><p>Bu kas için doğrulanmış sinir–damar–tutunma eşleştirmesi henüz eklenmedi.</p>';return;}panel.innerHTML='<b>Kasın bağlantıları</b><div class="connection-legend"><span style="--role:#58c9aa">Kas</span><span style="--role:#efce59">Sinir</span><span style="--role:#ed777c">Damar</span><span style="--role:#8eaff1">Başlangıç</span><span style="--role:#b799e8">Tutunma</span></div><p>'+esc(info.site)+'</p><p class="scope-note">Kemikler bütün olarak vurgulanır; tutunma bölgeleri metinde belirtilir. Noktasal yüzey işaretlemesi henüz yoktur.</p>'+info.rows.map(({record,role})=>'<button class="connection-link" style="--role:'+connectionColors[role]+'" data-connection="'+record.id+'">'+esc(displayName(record.name))+' ↗</button>').join('')+'<p>'+esc(info.note)+'</p>'+(info.missing.length?'<p>Kaynakta eşleşmeyen: '+esc(info.missing.map(x=>x.name).join(', '))+'</p>':'')+'<a href="'+info.url+'" target="_blank" rel="noreferrer">Anatomik ilişki kaynağı ↗</a>';panel.querySelectorAll('[data-connection]').forEach(b=>b.onclick=()=>{const o=objects.get(b.dataset.connection);if(o)frameObject(o);else toast('Bağlantı yükleniyor veya kaynakta bulunamadı.');});}
async function updateConnections(o){const ticket=++relationTicket;relationRoles.clear();relationRoot=null;if(!$('#showConnections').checked)return;const info=resolveConnections(o.userData.record,currentRecords());renderConnectionInfo();if(!info)return;const reference=sex;try{await Promise.all([...new Set(info.rows.map(x=>x.record.layer))].map(loadLayer));if(ticket!==relationTicket||selected!==o||sex!==reference)return;relationRoot=o;relationRoles.set(o.userData.record.id,'muscle');for(const {record,role} of info.rows){if(objects.has(record.id)){relationRoles.set(record.id,role);hidden.delete(record.id);}}refresh();renderConnectionInfo();}catch{if(ticket===relationTicket)toast('Bağlantı katmanları yüklenemedi.');}}
function renderPersonal(r){const panel=document.createElement('section');panel.className='personal-card';panel.innerHTML='<button id="favoriteToggle" aria-pressed="'+personal.has(r)+'">'+(personal.has(r)?'★ Favorilerimde':'☆ Favorilere ekle')+'</button><label for="personalNote">Çalışma notum</label><textarea id="personalNote" maxlength="4000" rows="3" placeholder="Bu yapıyla ilgili hatırlamak istediklerin…"></textarea><button id="saveNote">Notu kaydet</button><p id="noteStatus" role="status">Notlar yalnızca bu tarayıcıda saklanır.</p>';$('#detailContent').append(panel);$('#personalNote').value=personal.note(r);$('#favoriteToggle').onclick=e=>{try{const value=personal.toggle(r);e.target.setAttribute('aria-pressed',value);e.target.textContent=value?'★ Favorilerimde':'☆ Favorilere ekle';}catch{toast('Favori kaydedilemedi; tarayıcı depolaması dolu veya kapalı.');}};$('#saveNote').onclick=()=>{try{personal.setNote(r,$('#personalNote').value);$('#noteStatus').textContent='Not kaydedildi.';}catch{$('#noteStatus').textContent='Not kaydedilemedi; tarayıcı depolamasını kontrol et.';}};}
function showFavorites(){const list=personal.favorites(catalog);$('#favoritesList').innerHTML=list.length?list.map(r=>'<button data-favorite="'+esc(r.id)+'"><span>'+esc(displayName(r.name))+'</span><small>'+(recordSex(r)==='female'?'Kadın':'Erkek')+' · '+esc(layerName(r.layer))+'</small></button>').join(''):'<p>Henüz favorin yok. Bir yapı seçip ☆ Favorilere ekle düğmesine dokun.</p>';$('#favoritesDialog').showModal();document.querySelectorAll('[data-favorite]').forEach(b=>b.onclick=async()=>{b.disabled=true;const r=catalog.find(x=>x.id===b.dataset.favorite);try{if(recordSex(r)!==sex){$('#sexModel').value=recordSex(r);await switchSex(recordSex(r));}labels=true;$('#showLabels').checked=true;await selectById(r.id);$('#favoritesDialog').close();}catch{toast('Favori yapı yüklenemedi.');}finally{b.disabled=false;}});}
function saveStudyView(){const cut={};for(const id of ['cutAxis','cutPosition','cutYaw','cutPitch','cutThickness'])cut[id]=$('#'+id).value;for(const id of ['cutReverse','cutSlab','cutGuide'])cut[id]=$('#'+id).checked;const view={version:1,sex,layers:[...active],hidden:[...hidden].map(id=>objects.get(id)?.userData.record).filter(Boolean).map(recordKey),camera:camera.position.toArray(),target:controls.target.toArray(),cut,region,alpha,explosion,layerOpacity:{...layerOpacity},paletteMode,selected:selected?recordKey(selected.userData.record):null,isolated,labels};try{personal.saveView(view);toast('Görünüm bu tarayıcıya kaydedildi.');}catch{toast('Görünüm kaydedilemedi; tarayıcı depolamasını kontrol et.');}}
async function restoreStudyView(){const v=personal.getView();if(!validView(v)){toast('Kayıtlı görünüm yok veya kayıt okunamıyor.');return;}const b=$('#restoreView');b.disabled=true;try{if(v.sex!==sex){$('#sexModel').value=v.sex;await switchSex(v.sex);}relationTicket++;relationRoles.clear();selected=null;isolated=false;organMotion.enabled=false;$('#organAnimate').checked=false;active.clear();for(const id of v.layers)if(layerDefs.some(x=>x.id===id)&&currentRecords().some(r=>r.layer===id))active.add(id);await Promise.all([...active].map(loadLayer));hidden.clear();for(const r of currentRecords())if(v.hidden.includes(recordKey(r)))hidden.add(r.id);for(const id of Object.keys(layerOpacity))delete layerOpacity[id];for(const [id,n]of Object.entries(v.layerOpacity||{}))if(layerDefs.some(x=>x.id===id)&&Number.isFinite(n))layerOpacity[id]=Math.max(0,Math.min(1,n));alpha=Number.isFinite(v.alpha)?Math.max(.15,Math.min(1,v.alpha)):1;explosion=Number.isFinite(v.explosion)?Math.max(0,Math.min(1,v.explosion)):0;region=['all','arm','pelvis','head'].includes(v.region)?v.region:'all';$('#region').value=region;paletteMode=v.paletteMode==='atlas'?'atlas':'natural';document.querySelectorAll('[data-palette]').forEach(x=>x.setAttribute('aria-pressed',x.dataset.palette===paletteMode));$('#opacity').value=alpha*100;$('#opacityValue').value='%'+Math.round(alpha*100);$('#explode').value=explosion*100;$('#explodeValue').value='%'+Math.round(explosion*100);for(const id of ['cutAxis','cutPosition','cutYaw','cutPitch','cutThickness'])if(typeof v.cut[id]==='string')$('#'+id).value=v.cut[id];for(const id of ['cutReverse','cutSlab','cutGuide'])$('#'+id).checked=!!v.cut[id];if(!$('#cutAxis').value)$('#cutAxis').value='none';if(explosion>0)$('#cutAxis').value='none';labels=v.labels!==false;$('#showLabels').checked=labels;const r=currentRecords().find(r=>recordKey(r)===v.selected);if(r){await loadLayer(r.layer);choose(objects.get(r.id),{isolate:!!v.isolated});}else{$('#selectionLabel').hidden=true;$('#detailContent').innerHTML='<h2>Kaydedilen görünüm</h2><p>İncelemek için bir yapı seç.</p>';$('#details').classList.remove('open');}camera.position.fromArray(v.camera);controls.target.fromArray(v.target);controls.update();renderLayers();refresh();applyCut();toast('Kaydedilen görünüm açıldı.');}catch(e){console.error(e);toast('Görünüm yüklenemedi. Tekrar deneyebilirsin.');}finally{b.disabled=false;}}
